/* FUK Timetable Office - shared Vercel app with authenticated Supabase storage. */
const DEFAULT_SLOTS=[['08:00','10:00'],['10:00','12:00'],['12:00','13:00'],['13:00','14:00'],['14:00','16:00'],['16:00','18:00']];
const SEED_VENUES=[
['FCLT 1',500,'Permanent site','Five Hundred Capacity Lecture Theatre'],['FCLT 2',500,'Permanent site','New Five Hundred Capacity Lecture Theatre beside Faculty of Education Complex'],['FCLT 3',500,'Medical College','New Five Hundred Capacity Lecture Theatre'],
['AUD I',370,'Permanent site','New Auditorium 1 (Adjacent Language Laboratory)'],['AUD II',420,'Permanent site','New Auditorium 2 (adjacent Twin Lecture Theatre)'],['AUD III',200,'Permanent site','Auditorium 3 (Faculty of Agriculture Complex)'],
['LT 1',198,'Permanent site','Lecture Theatre 1 (Twin Lecture Theatre)'],['LT 1 R1',70,'Permanent site','LT1 Annex 1 (Twin Lecture Theatre)'],['LT 1 R2',70,'Permanent site','LT1 Annex 2 (Twin Lecture Theatre)'],['LT 2',198,'Permanent site','Lecture Theatre 2 (Twin Lecture Theatre)'],['LT 3',296,'Permanent site','New Three Hundred and Fifty Capacity Lecture Theatre beside Faculty of Education Complex'],['LT 4',200,'Permanent site','Lecture Theatre 4 (Twin Lecture Theatre), Faculty of Agriculture Complex'],['LT 5',200,'Permanent site','Lecture Theatre 5 (Twin Lecture Theatre), Faculty of Agriculture Complex'],
['OAUD',150,'Take-off site','Old University Auditorium (beside Science Complex)'],['NSA',120,'Permanent site','New Science Auditorium (New Faculty of Science Complex)'],...['I','II','III','IV'].map(x=>['DLC '+x,72,'Take-off site','Direct Labour Classroom '+x+' (behind Academic Staff Offices)']),
...['A101','A102','A103','A104'].map(x=>['RM '+x,50,'Permanent site','Lecture Rooms A, Behind LT1']),
...['C001','C002','C003','C004','C005','C101','C102','C103','C104','C105'].map((x,i)=>[x,[49,49,150,48,45,49,49,150,50,60][i],'Permanent site','Lecture Rooms C, Opposite Faculty of Management Sciences']),
['MCB LAB',30,'Permanent site','Microbiology Laboratory (New Faculty of Science Complex)','laboratory'],['ZOO LAB',30,'Permanent site','Zoology Laboratory (New Faculty of Science Complex)','laboratory'],['PLL LAB',30,'Permanent site','Plant Science Laboratory (New Faculty of Science Complex)','laboratory'],['GEOPHY LAB',30,'Permanent site','Geophysics Laboratory (New Faculty of Science Complex)','laboratory'],['BIO LAB',30,'Take-off site','Biology Laboratory located at the Science Complex','laboratory'],['CHM LAB',30,'Take-off site','Chemistry Laboratory located at the Science Complex','laboratory'],['PHY LAB',30,'Take-off site','Physics Laboratory located at the Science Complex','laboratory'],['AUD VIS LAB',null,'Permanent site','Audio visual Laboratory located at the Faculty of Agriculture Laboratories','laboratory'],
...['AEE 5C','AGN 5C','ANS 5C','SSC 5C'].map(x=>[x,null,'Permanent site','Faculty of Agriculture 500 Level Class']),['A300C',null,'Permanent site','A300C classroom'],['MISC',1096,'Permanent site','Multipurpose Indoor Sport Complex']
].map(v=>({id:'seed-'+v[0].toLowerCase().replace(/[^a-z0-9]+/g,'-'),name:v[0],capacity:v[1],location:v[2],description:v[3],type:v[4]||'classroom',active:true}));
const DEFAULT={version:1,settings:{session:'2026/2027',semester:'First semester',start:'',end:'',days:[1,2,3,4,5,6],slots:DEFAULT_SLOTS.map(x=>({start:x[0],end:x[1]})),examDuration:1,examGap:0,maxExamsPerCohortDay:0,examCapacityPercent:84},faculties:[],departments:[],courses:[],venues:SEED_VENUES,events:[]};
let db=loadDB(),page='dashboard',filters={type:'lecture',view:'grid',date:'',department:'',search:''};
let cloud={enabled:false,url:'',key:''},authToken='',refreshToken='',cloudVersion=null,lastSnapshot='',syncTimer=null,started=false;
function loadDB(){try{let v=JSON.parse(localStorage.getItem('fuk-timetable-v1'));if(v&&v.version===1)return {...structuredClone(DEFAULT),...v,settings:{...DEFAULT.settings,...v.settings},venues:v.venues||structuredClone(DEFAULT.venues)}}catch(e){}return structuredClone(DEFAULT)}
function save(){let snapshot=JSON.stringify(db);localStorage.setItem('fuk-timetable-v1',snapshot);let side=document.querySelector('#sideSession');if(side)side.textContent=db.settings.session+' · '+db.settings.semester;if(cloud.enabled&&authToken&&snapshot!==lastSnapshot){lastSnapshot=snapshot;clearTimeout(syncTimer);syncTimer=setTimeout(()=>syncCloud(snapshot),700)}}
function setStorageStatus(label,state=''){let el=$('#storageState');if(el){el.innerHTML=`<i></i> ${esc(label)}`;el.dataset.state=state}}
async function apiConfig(){let r=await fetch('/api/config');return r.ok?r.json():{configured:false}}
async function authRequest(path,body,token=''){let response=await fetch(cloud.url+'/auth/v1/'+path,{method:'POST',headers:{'Content-Type':'application/json','apikey':cloud.key,...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body)});let value=await response.json().catch(()=>({}));if(!response.ok)throw Error(value.msg||value.message||value.error_description||value.error||'Authentication failed.');return value}
async function restoreSession(){authToken=sessionStorage.getItem('fuk-auth-token')||'';refreshToken=sessionStorage.getItem('fuk-refresh-token')||'';if(!authToken)return false;let r=await fetch(cloud.url+'/auth/v1/user',{headers:{apikey:cloud.key,Authorization:'Bearer '+authToken}});if(r.ok)return true;if(refreshToken){try{let data=await authRequest('token?grant_type=refresh_token',{refresh_token:refreshToken});setTokens(data);return true}catch(e){}}clearTokens();return false}
function setTokens(data){authToken=data.access_token||'';refreshToken=data.refresh_token||'';sessionStorage.setItem('fuk-auth-token',authToken);sessionStorage.setItem('fuk-refresh-token',refreshToken)}
function clearTokens(){authToken='';refreshToken='';sessionStorage.removeItem('fuk-auth-token');sessionStorage.removeItem('fuk-refresh-token')}
function showAuth(message,error=''){let gate=$('#authGate');gate.hidden=false;$('#authMessage').textContent=message;$('#authError').textContent=error;document.querySelector('.sidebar').hidden=true;document.querySelector('.main').hidden=true}
function showWorkspace(){ $('#authGate').hidden=true;document.querySelector('.sidebar').hidden=false;document.querySelector('.main').hidden=false }
async function fetchCloudData(){let r=await fetch('/api/data',{headers:{Authorization:'Bearer '+authToken}});if(r.status===401&&refreshToken){let t=await authRequest('token?grant_type=refresh_token',{refresh_token:refreshToken});setTokens(t);r=await fetch('/api/data',{headers:{Authorization:'Bearer '+authToken}})}let data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Could not load the shared timetable data.');return data}
async function syncCloud(snapshot){try{setStorageStatus('Saving to shared workspace…','saving');let r=await fetch('/api/data',{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+authToken},body:JSON.stringify({expectedVersion:cloudVersion,payload:JSON.parse(snapshot)})});let data=await r.json().catch(()=>({}));if(r.status===409){setStorageStatus('Update conflict — reload to get latest data','error');toast('Another staff member saved changes first. Reload before making further edits.');return}if(!r.ok)throw Error(data.error||'Cloud save failed.');cloudVersion=data.version;setStorageStatus('All changes saved to shared workspace','saved')}catch(e){setStorageStatus('Cloud save failed — changes remain on this device','error');toast(e.message)}}
async function signIn(email,password){let data=await authRequest('token?grant_type=password',{email,password});setTokens(data);try{let record=await fetchCloudData();if(record.payload){db={...structuredClone(DEFAULT),...record.payload,settings:{...DEFAULT.settings,...record.payload.settings},venues:record.payload.venues||structuredClone(DEFAULT.venues)};cloudVersion=record.version;localStorage.setItem('fuk-timetable-v1',JSON.stringify(db))}else{cloudVersion=null;db=loadDB();await syncCloud(JSON.stringify(db))}lastSnapshot=JSON.stringify(db);showWorkspace();setStorageStatus('Shared workspace connected','saved');init()}catch(e){clearTokens();throw e}}
async function boot(){try{let config=await apiConfig();if(config.configured){cloud={enabled:true,url:config.url.replace(/\/$/,''),key:config.anonKey};$('#signInForm').onsubmit=async e=>{e.preventDefault();$('#authError').textContent='';try{await signIn($('#signInEmail').value.trim(),$('#signInPassword').value)}catch(err){$('#authError').textContent=err.message}};$('#signOut').onclick=()=>{authRequest('logout',{},authToken).catch(()=>{});clearTokens();showAuth('Sign in with an account issued by the timetable administrator.');};if(await restoreSession()){let record=await fetchCloudData();if(record.payload){db={...structuredClone(DEFAULT),...record.payload,settings:{...DEFAULT.settings,...record.payload.settings},venues:record.payload.venues||structuredClone(DEFAULT.venues)};cloudVersion=record.version;localStorage.setItem('fuk-timetable-v1',JSON.stringify(db))}else{cloudVersion=null;db=loadDB();await syncCloud(JSON.stringify(db))}lastSnapshot=JSON.stringify(db);showWorkspace();setStorageStatus('Shared workspace connected','saved');init()}else showAuth('Sign in with an account issued by the timetable administrator.');return}}catch(e){if(location.hostname.endsWith('.vercel.app')){showAuth('The shared timetable service is not configured yet.',e.message);return}}if(location.hostname.endsWith('.vercel.app')){showAuth('The shared timetable service is not configured yet.');return}cloud={enabled:false};setStorageStatus('Saved on this device','local');$('#signOut').hidden=true;init()}
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>Math.random().toString(36).slice(2,10), dateFmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):'', mins=t=>{let [h,m]=t.split(':').map(Number);return h*60+m}, duration=(a,b)=>mins(b)-mins(a), isOverlap=(a,b,c,d)=>mins(a)<mins(d)&&mins(c)<mins(b);
function toast(msg){let e=$('#toast');e.textContent=msg;e.className='toast show';setTimeout(()=>e.className='toast',2600)}
function nav(p){page=p;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===p));$('#pageTitle').textContent=({'dashboard':'Overview','schedule':'Timetables','courses':'Courses','venues':'Venues','structure':'Faculties & departments','reports':'Reports & data','settings':'Academic settings'})[p];$('#breadcrumb').textContent='WORKSPACE / '+$('#pageTitle').textContent.toUpperCase();render()}
function render(){save();({dashboard:renderDashboard,schedule:renderSchedule,courses:renderCourses,venues:renderVenues,structure:renderStructure,reports:renderReports,settings:renderSettings}[page]||renderDashboard)()}
function stat(label,value,note,icon){return `<div class="stat-card"><div class="stat-icon">${icon}</div><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
function renderDashboard(){let active=db.venues.filter(v=>v.active).length,lect=db.events.filter(e=>e.type==='lecture').length,ex=db.events.filter(e=>e.type==='exam').length;$('#app').innerHTML=`<div class="welcome"><div><h2>Good day, timetable officer</h2><p>Manage academic schedules, spaces and course data for ${esc(db.settings.session)}.</p></div><div class="date-label">${new Date().toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div></div><div class="stat-grid">${stat('Active venues',active,'Across the university','⌂')}${stat('Courses',db.courses.length,'In the course register','▤')}${stat('Lecture sessions',lect,'Currently scheduled','▦')}${stat('Exam sessions',ex,'Currently scheduled','◇')}</div><div class="grid-two"><div class="panel"><div class="panel-head"><div><h3>Schedule activity</h3><p>Current timetable coverage</p></div><button class="button small" data-go="schedule">Open timetable →</button></div>${db.events.length?`<div class="action-list">${['lecture','exam'].map(t=>{let n=db.events.filter(e=>e.type===t).length,pct=db.courses.length?Math.min(100,Math.round(new Set(db.events.filter(e=>e.type===t).map(x=>x.courseId)).size/db.courses.length*100)):100;return `<div class="action-row"><div class="action-icon">${t==='exam'?'◇':'▦'}</div><div style="flex:1"><strong>${t==='exam'?'Examination':'Lecture'} timetable</strong><small>${n} of ${db.courses.length} course sessions scheduled</small><div class="progressline" style="margin-top:8px"><i style="width:${pct}%"></i></div></div><span class="tag">${pct}%</span></div>`}).join('')}</div>`:`<div class="empty"><div><div class="empty-icon">▦</div><strong>No timetable generated yet</strong>Add courses, then generate a lecture or examination schedule.</div></div>`}</div><div class="panel"><div class="panel-head"><div><h3>Get started</h3><p>Set up the timetable workflow</p></div></div><div class="action-list"><div class="action-row"><div class="action-icon">◎</div><div><strong>Set up academic structure</strong><small>Add faculties and departments</small></div><button class="button small" data-go="structure">Open</button></div><div class="action-row"><div class="action-icon">▤</div><div><strong>Enter course register</strong><small>Include cohort, enrolment and lecturer</small></div><button class="button small" data-go="courses">Open</button></div><div class="action-row"><div class="action-icon">⌂</div><div><strong>Review seeded venues</strong><small>${active} spaces from the provisional reference</small></div><button class="button small" data-go="venues">Open</button></div><div class="action-row"><div class="action-icon">⚙</div><div><strong>Configure session dates</strong><small>Set semester range and scheduling rules</small></div><button class="button small" data-go="settings">Open</button></div></div></div></div>`}
function renderCourses(){let rows=db.courses.filter(c=>!filters.search||[c.code,c.title,c.department,c.lecturer,c.level].join(' ').toLowerCase().includes(filters.search.toLowerCase()));$('#app').innerHTML=`<p class="page-intro">Maintain the course register used by both timetable generators. <strong>${db.courses.length} courses</strong></p><div class="toolbar"><input class="input search" id="courseSearch" placeholder="Search courses, lecturers…" value="${esc(filters.search)}"><span class="spacer"></span><button class="button" data-import="courses">Import CSV</button><button class="button" data-export="courses">Export CSV</button><button class="button primary" data-add="course">＋ Add course</button></div><div class="table-card"><div class="table-scroll"><table><thead><tr><th>Course</th><th>Department</th><th>Level</th><th>Cohort</th><th>Students</th><th>Lecturer</th><th>Duration</th><th>Actions</th></tr></thead><tbody>${rows.length?rows.map(c=>`<tr><td><strong>${esc(c.code)}</strong><br><span class="small-note">${esc(c.title)}</span></td><td>${esc(c.department||'—')}</td><td>${esc(c.level||'—')}</td><td>${esc(c.cohort||'—')}</td><td>${Number(c.students)||0}</td><td>${esc(c.lecturer||'—')}</td><td>${c.duration||1} slot${c.duration==1?'':'s'}</td><td><div class="row-actions"><button class="button small" data-edit="course" data-id="${c.id}">Edit</button><button class="button small danger" data-delete="course" data-id="${c.id}">Delete</button></div></td></tr>`).join(''):`<tr><td colspan="8"><div class="empty"><div><div class="empty-icon">▤</div><strong>No courses in the register</strong>Add the courses to schedule or import a CSV register.</div></div></td></tr>`}</tbody></table></div></div>`}
function renderVenues(){let active=db.venues.filter(v=>v.active),archived=db.venues.filter(v=>!v.active);$('#app').innerHTML=`<p class="page-intro">Venue names, capacities and site descriptions are seeded from the provisional 2026/2027 lecture timetable PDF. <strong>${active.length} active · ${archived.length} archived</strong></p><div class="toolbar"><input class="input search" id="venueSearch" placeholder="Search venues…" value="${esc(filters.search)}"><span class="spacer"></span><button class="button" data-import="venues">Import CSV</button><button class="button" data-export="venues">Export CSV</button><button class="button primary" data-add="venue">＋ Add venue</button></div><div class="table-card"><div class="table-scroll"><table><thead><tr><th>Venue</th><th>Capacity</th><th>Type</th><th>Location</th><th>Description</th><th>Timetable status</th><th>Actions</th></tr></thead><tbody>${active.filter(v=>!filters.search||[v.name,v.location,v.description].join(' ').toLowerCase().includes(filters.search.toLowerCase())).map(v=>`<tr><td><strong>${esc(v.name)}</strong></td><td>${v.capacity||'—'}</td><td><span class="tag gray">${esc(v.type)}</span></td><td>${esc(v.location||'—')}</td><td>${esc(v.description||'—')}</td><td><span class="tag">Active</span></td><td><div class="row-actions"><button class="button small" data-edit="venue" data-id="${v.id}">Edit</button><button class="button small danger" data-archive="${v.id}">Archive</button></div></td></tr>`).join('')||'<tr><td colspan="7">No matching venues.</td></tr>'}${archived.length?`<tr><td colspan="7" style="background:#fafbf9;color:#829188;font-weight:700">ARCHIVED SPACES</td></tr>${archived.map(v=>`<tr><td><strong>${esc(v.name)}</strong></td><td>${v.capacity||'—'}</td><td>${esc(v.type)}</td><td>${esc(v.location||'—')}</td><td>${esc(v.description||'—')}</td><td><span class="tag gray">Archived</span></td><td><button class="button small" data-unarchive="${v.id}">Restore</button></td></tr>`).join('')}`:''}</tbody></table></div></div>`}
function renderStructure(){let facRows=db.faculties.map(f=>`<tr><td><strong>${esc(f.name)}</strong></td><td>${esc(f.code||'—')}</td><td>${db.departments.filter(d=>d.facultyId===f.id).length}</td><td><div class="row-actions"><button class="button small" data-edit="faculty" data-id="${f.id}">Edit</button><button class="button small danger" data-delete="faculty" data-id="${f.id}">Delete</button></div></td></tr>`).join(''),depRows=db.departments.map(d=>`<tr><td><strong>${esc(d.name)}</strong></td><td>${esc(db.faculties.find(f=>f.id===d.facultyId)?.name||'—')}</td><td>${esc(d.code||'—')}</td><td><div class="row-actions"><button class="button small" data-edit="department" data-id="${d.id}">Edit</button><button class="button small danger" data-delete="department" data-id="${d.id}">Delete</button></div></td></tr>`).join('');$('#app').innerHTML=`<p class="page-intro">Create the university structure used to group course data. Course department and cohort fields remain editable on each course.</p><div class="grid-two"><div class="panel"><div class="panel-head"><div><h3>Faculties</h3><p>${db.faculties.length} records</p></div><button class="button primary small" data-add="faculty">＋ Add faculty</button></div><div class="table-scroll"><table><thead><tr><th>Faculty</th><th>Code</th><th>Departments</th><th>Actions</th></tr></thead><tbody>${facRows||'<tr><td colspan="4" class="small-note">No faculties added yet.</td></tr>'}</tbody></table></div></div><div class="panel"><div class="panel-head"><div><h3>Departments</h3><p>${db.departments.length} records</p></div><button class="button primary small" data-add="department">＋ Add department</button></div><div class="table-scroll"><table><thead><tr><th>Department</th><th>Faculty</th><th>Code</th><th>Actions</th></tr></thead><tbody>${depRows||'<tr><td colspan="4" class="small-note">No departments added yet.</td></tr>'}</tbody></table></div></div></div>`}
function renderSchedule(){let ev=db.events.filter(e=>e.type===filters.type&&(!filters.department||e.department===filters.department)&&(!filters.date||e.date===filters.date)),days=daysInRange(db.settings.start,db.settings.end).filter(d=>db.settings.days.includes(new Date(d+'T12:00:00').getDay()));let dates=[...new Set(ev.map(e=>e.date))].sort();let displayDays=filters.date?[filters.date]:dates.length?dates:days.slice(0,6);let slots=db.settings.slots;$('#app').innerHTML=`<div class="filter-bar"><select class="select" id="scheduleType"><option value="lecture" ${filters.type==='lecture'?'selected':''}>Lecture timetable</option><option value="exam" ${filters.type==='exam'?'selected':''}>Examination timetable</option></select><select class="select" id="scheduleView"><option value="grid" ${filters.view==='grid'?'selected':''}>By date</option><option value="list" ${filters.view==='list'?'selected':''}>List view</option></select><input type="date" class="input" id="scheduleDate" value="${filters.date}" title="Filter by date"><select class="select" id="scheduleDepartment"><option value="">All departments</option>${[...new Set(db.courses.map(c=>c.department).filter(Boolean))].sort().map(d=>`<option ${filters.department===d?'selected':''}>${esc(d)}</option>`).join('')}</select><span class="spacer"></span><button class="button" data-add="event">＋ Add session</button><button class="button no-print" data-print>Print / Save PDF</button><button class="button primary" data-generate>Generate ${filters.type==='exam'?'exams':'lectures'}</button></div><div class="print-heading"><h1>Federal University of Kashere</h1><p>${esc(db.settings.semester)} ${esc(db.settings.session)} · ${filters.type==='exam'?'Examination':'Lecture'} timetable</p></div>${db.courses.length===0?'<div class="notice warn">Add courses before generating a timetable. A generated timetable uses the configured date range, days, time periods and active venue capacities.</div>':''}${filters.view==='grid'?renderGrid(ev,displayDays,slots):renderList(ev)}</div>`}
function renderGrid(ev,dates,slots){return `<div class="timetable-wrap"><table class="timetable"><thead><tr><th>Date</th>${slots.map(s=>`<th>${esc(s.start)}–${esc(s.end)}</th>`).join('')}</tr></thead><tbody>${dates.map(d=>`<tr><td>${dateFmt(d)}<br><span class="small-note">${new Date(d+'T12:00:00').toLocaleDateString(undefined,{weekday:'long'})}</span></td>${slots.map(s=>{let found=ev.filter(e=>e.date===d&&isOverlap(e.start,e.end,s.start,s.end));return `<td>${found.map(e=>`<div class="slot-card ${e.type==='exam'?'exam':''}"><strong>${esc(e.courseCode)} · ${esc(e.courseTitle||'')}</strong>${esc(e.cohort)}<br>${esc(e.venueName)}<br><small>${esc(e.start)}–${esc(e.end)} · ${esc(e.lecturer||'')}</small><div class="row-actions no-print" style="margin-top:5px"><button class="button small" data-edit="event" data-id="${e.id}">Edit</button><button class="button small danger" data-delete="event" data-id="${e.id}">×</button></div></div>`).join('')||'<span class="small-note">—</span>'}</td>`}).join('')}</tr>`).join('')||`<tr><td colspan="${slots.length+1}"><div class="empty"><div>No sessions to display. Generate a timetable or add a session.</div></div></td></tr>`}</tbody></table></div>`}
function renderList(ev){return `<div class="table-card"><div class="table-scroll"><table><thead><tr><th>Date</th><th>Time</th><th>Course</th><th>Cohort</th><th>Venue</th><th>Lecturer</th><th>Actions</th></tr></thead><tbody>${ev.sort(eventSort).map(e=>`<tr><td>${dateFmt(e.date)}</td><td>${e.start}–${e.end}</td><td><strong>${esc(e.courseCode)}</strong><br><span class="small-note">${esc(e.courseTitle)}</span></td><td>${esc(e.cohort)}</td><td>${esc(e.venueName)}</td><td>${esc(e.lecturer||'—')}</td><td><div class="row-actions"><button class="button small" data-edit="event" data-id="${e.id}">Edit</button><button class="button small danger" data-delete="event" data-id="${e.id}">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">No sessions to display.</div></td></tr>'}</tbody></table></div></div>`}
function eventSort(a,b){return a.date.localeCompare(b.date)||a.start.localeCompare(b.start)}
function daysInRange(a,b){let out=[];if(!a||!b)return out;let d=new Date(a+'T12:00:00'),end=new Date(b+'T12:00:00'),fmt=x=>`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;for(;d<=end;d.setDate(d.getDate()+1))out.push(fmt(d));return out}
function renderSettings(){let s=db.settings;$('#app').innerHTML=`<div class="grid-two"><div class="panel"><div class="panel-head"><div><h3>Academic session</h3><p>Used in timetable headings and generation</p></div></div><div class="form-grid"><div class="field"><label>Academic session</label><input class="input" id="cfgSession" value="${esc(s.session)}" placeholder="2026/2027"></div><div class="field"><label>Semester</label><input class="input" id="cfgSemester" value="${esc(s.semester)}"></div><div class="field"><label>Start date</label><input class="input" type="date" id="cfgStart" value="${s.start}"></div><div class="field"><label>End date</label><input class="input" type="date" id="cfgEnd" value="${s.end}"></div><div class="field full"><label>Scheduling days</label><div style="display:flex;gap:12px;flex-wrap:wrap">${[['Mon',1],['Tue',2],['Wed',3],['Thu',4],['Fri',5],['Sat',6],['Sun',0]].map(([d,n])=>`<label style="font-size:11px"><input type="checkbox" class="cfgDay" value="${n}" ${s.days.includes(n)?'checked':''}> ${d}</label>`).join('')}</div><small class="small-note">Sunday is blocked by the generator even if selected here.</small></div></div><div class="setting-block"><h4>Daily time periods</h4><p>Default periods match the provisional university reference. Times can be adjusted to suit the session.</p><div class="slot-list" id="slotList">${s.slots.map((x,i)=>`<div class="slot-row"><input class="input cfgSlotStart" type="time" value="${x.start}"><input class="input cfgSlotEnd" type="time" value="${x.end}"><button class="button small danger" data-remove-slot="${i}">Remove</button></div>`).join('')}</div><button class="button small" style="margin-top:9px" data-add-slot>＋ Add period</button></div><button class="button primary" style="margin-top:16px" data-save-settings>Save academic settings</button></div><div class="panel"><div class="panel-head"><div><h3>Examination rules</h3><p>Set local exam preferences; these are not specified in the lecture reference PDF.</p></div></div><div class="notice warn">Examination rules are configurable assumptions. Confirm them with your examination office before publishing.</div><div class="form-grid"><div class="field"><label>Exam length (time periods)</label><input class="input" type="number" min="1" max="6" id="cfgExamDuration" value="${s.examDuration}"></div><div class="field"><label>Minimum gap between exams for a cohort (days)</label><input class="input" type="number" min="0" max="14" id="cfgExamGap" value="${s.examGap}"></div><div class="field full"><label>Maximum exams per cohort per day (0 = no limit)</label><input class="input" type="number" min="0" max="6" id="cfgMaxExams" value="${s.maxExamsPerCohortDay}"></div><div class="field full"><label>Exam room occupancy target (%)</label><input class="input" type="number" min="50" max="100" id="cfgExamCapacityPercent" value="${s.examCapacityPercent??84}"><small class="small-note">A 500-seat venue at 84% provides space for about 420 candidates. Larger cohorts are split across multiple rooms at the same time.</small></div></div><button class="button primary" style="margin-top:16px" data-save-settings>Save academic settings</button><div class="setting-block" style="margin-top:18px"><h4>Reference template</h4><p>Six daily periods from 8:00am to 6:00pm. Seed venues and capacity values were taken from the provisional First Semester 2026/2027 timetable PDF. Blank capacities in that reference are retained as unspecified.</p></div></div></div>`}
function renderReports(){let total=db.events.length, byDept={};db.events.forEach(e=>byDept[e.department||'Unassigned']=(byDept[e.department||'Unassigned']||0)+1);$('#app').innerHTML=`<p class="page-intro">Review schedule coverage and move data into or out of the timetable workspace.</p><div class="stat-grid">${stat('Scheduled sessions',total,'A split paper counts once per venue','▦')}${stat('Unscheduled courses',Math.max(0,db.courses.length-new Set(db.events.map(e=>e.courseId)).size),'Compared with registered courses','▤')}${stat('Active venues',db.venues.filter(v=>v.active).length,'Available for generation','⌂')}${stat('Departments',db.departments.length,'In academic structure','◎')}</div><div class="panel exam-summary"><div class="panel-head"><div><h3>Examination summaries by faculty, department and level</h3><p>Each paper shows every exam date, time, venue and allocated student count.</p></div><button class="button no-print" data-print>Print / Save PDF</button></div><div class="toolbar"><select class="select" id="summaryFaculty"><option value="">All faculties</option>${[...new Set(db.courses.map(c=>c.faculty).filter(Boolean))].sort().map(f=>`<option>${esc(f)}</option>`).join('')}</select><select class="select" id="summaryDepartment"><option value="">All departments</option>${[...new Set(db.courses.map(c=>c.department).filter(Boolean))].sort().map(f=>`<option>${esc(f)}</option>`).join('')}</select><select class="select" id="summaryLevel"><option value="">All levels</option>${[...new Set(db.courses.map(c=>c.level).filter(Boolean))].sort().map(f=>`<option>${esc(f)}</option>`).join('')}</select></div>${renderExamSummaryTables()}</div><div class="grid-two" style="margin-top:16px"><div class="panel"><div class="panel-head"><div><h3>Scheduled sessions by department</h3><p>Current generated and manually assigned sessions</p></div></div>${Object.keys(byDept).length?`<div class="table-scroll"><table><thead><tr><th>Department</th><th>Sessions</th><th>Lecture</th><th>Exam</th></tr></thead><tbody>${Object.entries(byDept).sort().map(([d,n])=>`<tr><td>${esc(d)}</td><td>${n}</td><td>${db.events.filter(e=>e.department===d&&e.type==='lecture').length}</td><td>${db.events.filter(e=>e.department===d&&e.type==='exam').length}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Generate a schedule to see department coverage.</div>'}</div><div class="panel"><div class="panel-head"><div><h3>Import and backup</h3><p>CSV files open directly in Excel and other spreadsheet tools</p></div></div><div class="action-list"><div class="action-row"><div class="action-icon">↓</div><div><strong>Export full backup</strong><small>JSON backup with settings, register, venues and sessions</small></div><button class="button small" data-backup>Download</button></div><div class="action-row"><div class="action-icon">↑</div><div><strong>Restore backup</strong><small>Restore a JSON backup into this browser</small></div><button class="button small" data-restore>Choose file</button></div><div class="action-row"><div class="action-icon">▦</div><div><strong>Export timetable</strong><small>Download current lecture and exam schedules as CSV</small></div><button class="button small" data-export="events">Download</button></div><div class="action-row"><div class="action-icon">▤</div><div><strong>Export course register</strong><small>Download course data as CSV</small></div><button class="button small" data-export="courses">Download</button></div></div><p class="small-note" style="margin-top:14px">Data is stored locally in this browser. Download regular backups to move data between devices.</p></div></div>`}
function renderExamSummaryTables(){
 let faculty=$('#summaryFaculty')?.value||'',department=$('#summaryDepartment')?.value||'',level=$('#summaryLevel')?.value||'';
 let ev=db.events.filter(e=>e.type==='exam').filter(e=>{let c=db.courses.find(x=>x.id===e.courseId);return (!faculty&&(true)||((c?.faculty||e.faculty||'')===faculty))&&(!department||(e.department||'')===department)&&(!level||((c?.level||e.level||'')===level))});
 let groups=[['Faculty',e=>db.courses.find(c=>c.id===e.courseId)?.faculty||e.faculty||'Unassigned'],['Department',e=>e.department||'Unassigned'],['Level',e=>db.courses.find(c=>c.id===e.courseId)?.level||e.level||'Unassigned']];
 return groups.map(([label,key])=>{
  let by={};ev.forEach(e=>{let n=key(e);if(!by[n])by[n]=[];by[n].push(e)});
  let sections=Object.keys(by).sort().map(name=>{
   let papers={};by[name].forEach(e=>{let k=(e.courseId||e.courseCode)+'|'+e.date+'|'+e.start+'|'+e.end;if(!papers[k])papers[k]={...e,allocations:[]};papers[k].allocations.push(e)});
   let rows=Object.values(papers).sort(eventSort).map(p=>`<tr><td><strong>${esc(p.courseCode)}</strong><br><span class="small-note">${esc(p.courseTitle||'')}</span></td><td>${esc(p.cohort||'—')}</td><td>${p.totalStudents||p.allocations.reduce((n,a)=>n+(Number(a.students)||0),0)}</td><td>${dateFmt(p.date)}<br>${esc(p.start)}–${esc(p.end)}</td><td>${p.allocations.map(a=>`${esc(a.venueName)}: ${a.students} students`).join('<br>')}</td></tr>`).join('');
   return `<section class="summary-group"><h5>${esc(name)}</h5><div class="table-scroll"><table><thead><tr><th>Paper</th><th>Cohort</th><th>Candidates</th><th>Exam date &amp; time</th><th>Venue allocation</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
  }).join('');
  return `<h4 class="summary-heading">${label} summaries</h4>${sections||`<div class="empty">No examination papers match this ${label.toLowerCase()}.</div>`}`;
 }).join('')||'<div class="empty">Generate an examination timetable to populate summaries.</div>';
}
function openModal(title,body,saveText='Save',onSave=null){let root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h3>${title}</h3><button class="modal-close" data-modal-close>×</button></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="button" data-modal-close>Cancel</button><button class="button primary" id="modalSave">${saveText}</button></div></div></div>`;root.querySelectorAll('[data-modal-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};$('#modalSave').onclick=()=>{if(onSave&&onSave()===false)return;root.innerHTML='';render()}}
function field(label,name,value='',type='text',full=false,extra=''){return `<div class="field ${full?'full':''}"><label>${label}</label><input class="input" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function selectField(label,name,options,value='',full=false){return `<div class="field ${full?'full':''}"><label>${label}</label><select class="select" name="${name}">${options.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(value)?'selected':''}>${esc(o[1])}</option>`).join('')}</select></div>`}
function formValues(){let o={};$('#modalRoot').querySelectorAll('[name]').forEach(x=>o[x.name]=x.type==='number'?(x.value===''?null:Number(x.value)):x.value.trim());return o}
function addEdit(kind,id){let item=id?collection(kind).find(x=>x.id===id):null;if(kind==='event'){eventModal(item);return}let vals=item||{},body='';
if(kind==='course')body=`<div class="form-grid">${field('Course code *','code',vals.code||'')}${field('Course title *','title',vals.title||'')}${selectField('Department','department',[['','Select department'],...db.departments.map(d=>[d.name,d.name])],vals.department||'')}${field('Faculty (optional)','faculty',vals.faculty||'')}${field('Level','level',vals.level||'')}${field('Cohort key *','cohort',vals.cohort||'', 'text',false,'placeholder="e.g. Biology 200"')}${field('Student count','students',vals.students??0,'number')}${field('Lecturer','lecturer',vals.lecturer||'')}${field('Lecture duration (periods)','duration',vals.duration||1,'number',false,'min="1" max="6"')}${selectField('Preferred venue type','venueType',[['any','Any venue'],['classroom','Classroom / hall'],['laboratory','Laboratory']],vals.venueType||'any')}</div><p class="small-note">Cohort keys identify groups that cannot have simultaneous sessions. Use the same key for courses taken by the same student group.</p>`;
if(kind==='venue')body=`<div class="form-grid">${field('Venue name *','name',vals.name||'')}${field('Capacity (leave blank if unspecified)','capacity',vals.capacity??'','number')}${selectField('Venue type','type',[['classroom','Classroom / hall'],['laboratory','Laboratory'],['other','Other']],vals.type||'classroom')}${field('Location / site','location',vals.location||'')}${field('Description','description',vals.description||'','text',true)}</div>`;
if(kind==='faculty')body=`<div class="form-grid">${field('Faculty name *','name',vals.name||'')}${field('Faculty code','code',vals.code||'')}</div>`;
if(kind==='department')body=`<div class="form-grid">${field('Department name *','name',vals.name||'')}${field('Department code','code',vals.code||'')}${selectField('Faculty *','facultyId',[['','Select faculty'],...db.faculties.map(f=>[f.id,f.name])],vals.facultyId||'',true)}</div>`;
openModal(`${item?'Edit':'Add'} ${kind}`,body,'Save',()=>{let data=formValues();if(!data.name&&kind!=='course'||kind==='course'&&(!data.code||!data.title||!data.cohort)){toast('Complete the required fields.');return false}if(kind==='course'&&db.courses.some(c=>c.code.toLowerCase()===data.code.toLowerCase()&&c.id!==id)){toast('That course code is already in the register.');return false}if(kind==='venue'&&db.venues.some(v=>v.name.toLowerCase()===data.name.toLowerCase()&&v.id!==id)){toast('A venue with that name already exists.');return false}if(data.capacity==='')data.capacity=null;if(item)Object.assign(item,data);else collection(kind).push({id:uid(),...data,...(kind==='venue'?{active:true}:{})});toast(`${kind[0].toUpperCase()+kind.slice(1)} saved.`)})}
function collection(k){return ({course:db.courses,venue:db.venues,faculty:db.faculties,department:db.departments,event:db.events})[k]}
function eventModal(item){let v=item||{},course=db.courses.find(c=>c.id===v.courseId),type=v.type||filters.type;let courseOpts=[['','Manual / select a course'],...db.courses.map(c=>[c.id,c.code+' — '+c.title])];let body=`<div class="form-grid">${selectField('Schedule type','type',[['lecture','Lecture'],['exam','Examination']],type)}${selectField('Course','courseId',courseOpts,v.courseId||'')}${field('Course code *','courseCode',v.courseCode||course?.code||'')}${field('Course title','courseTitle',v.courseTitle||course?.title||'')}${field('Date *','date',v.date||db.settings.start,'date')}${selectField('Venue *','venueId',[['','Select venue'],...db.venues.filter(x=>x.active).map(x=>[x.id,`${x.name}${x.capacity?' ('+x.capacity+')':''}`])],v.venueId||'')}${field('Start time *','start',v.start||db.settings.slots[0]?.start||'08:00','time')}${field('End time *','end',v.end||db.settings.slots[0]?.end||'10:00','time')}${field('Cohort key *','cohort',v.cohort||course?.cohort||'')}${field('Students','students',v.students??course?.students??0,'number')}${field('Lecturer','lecturer',v.lecturer||course?.lecturer||'')}${field('Department','department',v.department||course?.department||'')}</div>`;
openModal(`${item?'Edit':'Add'} timetable session`,body,'Save session',()=>{let d=formValues(),venue=db.venues.find(x=>x.id===d.venueId);let ev={...d,id:item?.id||uid(),venueName:venue?.name||'',duration:duration(d.start,d.end)};let problem=validateEvent(ev,item?.id);if(problem){toast(problem);return false}if(item)Object.assign(item,ev);else db.events.push(ev);toast('Session saved with no conflicts.')});$('#modalRoot').querySelector('[name="courseId"]').onchange=e=>{let c=db.courses.find(x=>x.id===e.target.value);if(!c)return;let f=$('#modalRoot').querySelector('[name="courseCode"]');f.value=c.code;$('#modalRoot').querySelector('[name="courseTitle"]').value=c.title;$('#modalRoot').querySelector('[name="cohort"]').value=c.cohort;$('#modalRoot').querySelector('[name="students"]').value=c.students||0;$('#modalRoot').querySelector('[name="lecturer"]').value=c.lecturer||'';$('#modalRoot').querySelector('[name="department"]').value=c.department||''}}
function validateEvent(e,ignoreId=null,existing=db.events){if(!e.date||!e.start||!e.end||mins(e.start)>=mins(e.end))return 'Choose a valid date and time range.';if(!db.settings.slots.some(s=>s.start===e.start)||!db.settings.slots.some(s=>s.end===e.end))return 'Session times must align with configured period boundaries.';let dt=new Date(e.date+'T12:00:00');if(dt.getDay()===0)return 'Sunday scheduling is disabled.';if(e.date<db.settings.start||e.date>db.settings.end)return 'Session date must be within the configured academic date range.';let venue=db.venues.find(v=>v.id===e.venueId);if(!venue||!venue.active)return 'Choose an active venue.';let cap=Number(venue.capacity)||0,limit=e.type==='exam'&&cap?Math.floor(cap*(Number(db.settings.examCapacityPercent??84)/100)):cap;if(limit&&Number(e.students)>limit)return `${venue.name} safe exam capacity (${limit}, ${db.settings.examCapacityPercent??84}% of ${cap}) is below this allocation.`;for(let o of existing){if(o.id===ignoreId||o.date!==e.date||!isOverlap(e.start,e.end,o.start,o.end))continue;if(o.venueId===e.venueId)return `Venue conflict: ${venue.name} is already booked.`;let sameSplit=e.type==='exam'&&o.type==='exam'&&e.courseId&&o.courseId===e.courseId&&e.totalStudents&&o.totalStudents===e.totalStudents&&e.date===o.date&&e.start===o.start&&e.end===o.end;if(sameSplit)continue;if((e.courseId&&o.courseId===e.courseId)||(!e.courseId&&e.courseCode&&o.courseCode===e.courseCode))return `Course conflict: ${e.courseCode} already has a session at this time.`;if(e.cohort&&o.cohort===e.cohort)return `Cohort conflict: ${e.cohort} already has a session at this time.`;if(e.lecturer&&o.lecturer&&o.lecturer.toLowerCase()===e.lecturer.toLowerCase())return `Lecturer conflict: ${e.lecturer} already has a session at this time.`}return ''}
function deleteItem(kind,id){let arr=collection(kind),item=arr.find(x=>x.id===id);if(!item)return;if(kind==='faculty'&&db.departments.some(d=>d.facultyId===id)){toast('Move or delete this faculty’s departments first.');return}if(kind==='department'&&db.courses.some(c=>c.department===item.name)){toast('Update the courses assigned to this department first.');return}if(kind==='course')db.events=db.events.filter(e=>e.courseId!==id);arr.splice(arr.indexOf(item),1);toast(`${kind[0].toUpperCase()+kind.slice(1)} deleted.`);render()}
function generate(type){if(!db.courses.length){toast('Add courses before generating a timetable.');return}let conf=db.settings,days=daysInRange(conf.start,conf.end).filter(d=>new Date(d+'T12:00:00').getDay()!==0&&conf.days.includes(new Date(d+'T12:00:00').getDay()));if(!days.length){toast('No schedulable dates in this date range.');return}let others=db.events.filter(e=>e.type!==type);db.events=db.events.filter(e=>e.type!==type);let slots=conf.slots,venues=db.venues.filter(v=>v.active),courses=[...db.courses].sort((a,b)=>(Number(b.students)||0)-(Number(a.students)||0));let generated=[],failed=[];
for(let c of courses){let needed=type==='exam'?Math.max(1,Number(conf.examDuration)||1):Math.max(1,Number(c.duration)||1),headcount=Math.max(0,Number(c.students)||0);let candidates=[];for(let date of days)for(let i=0;i<=slots.length-needed;i++){let start=slots[i].start,end=slots[i+needed-1].end;if(mins(end)<=mins(start))continue;candidates.push({date,start,end,i})}let placed=null;
for(let cand of candidates){let existing=[...others,...generated];if(type==='exam'){let same=[...new Map(generated.filter(e=>e.cohort===c.cohort).map(e=>[e.courseId+'|'+e.date,e])).values()];if(conf.maxExamsPerCohortDay>0&&new Set(same.filter(e=>e.date===cand.date).map(e=>e.courseId)).size>=conf.maxExamsPerCohortDay)continue;let gap=Number(conf.examGap)||0;if(same.some(e=>Math.abs((new Date(e.date)-new Date(cand.date))/86400000)<=gap))continue}
let eligible=venues.filter(v=>c.venueType==='any'||!c.venueType||v.type===c.venueType).sort((a,b)=>(Number(b.capacity)||0)-(Number(a.capacity)||0));let usable=eligible.filter(v=>!existing.some(o=>o.date===cand.date&&isOverlap(cand.start,cand.end,o.start,o.end)&&(o.venueId===v.id||o.cohort===c.cohort||(o.lecturer&&c.lecturer&&o.lecturer.toLowerCase()===c.lecturer.toLowerCase())||o.courseId===c.id)));let allocations=[];
if(type==='exam'&&headcount>0){let remaining=headcount;for(let v of usable){if(!v.capacity)continue;let safe=Math.floor(Number(v.capacity)*(Number(conf.examCapacityPercent??84)/100)),take=Math.min(safe,remaining);if(take>0){allocations.push([v,take]);remaining-=take}if(remaining<=0)break}if(remaining>0){let unknown=usable.find(v=>!Number(v.capacity));if(unknown){allocations=[[unknown,headcount]];remaining=0}}if(remaining>0)allocations=[]}
else if(type==='exam'&&headcount===0){if(usable.length)allocations=[[usable[0],0]]}
else {let single=usable.filter(v=>!v.capacity||Number(v.capacity)>=headcount).sort((a,b)=>(Number(a.capacity)||Infinity)-(Number(b.capacity)||Infinity))[0];if(single)allocations=[[single,headcount]]}
if(!allocations.length)continue;let common={type,courseId:c.id,courseCode:c.code,courseTitle:c.title,department:c.department||'',faculty:c.faculty||'',level:c.level||'',cohort:c.cohort,lecturer:c.lecturer||'',totalStudents:headcount,date:cand.date,start:cand.start,end:cand.end,duration:needed};let proposed=allocations.map(([v,n])=>({...common,id:uid(),students:n,venueId:v.id,venueName:v.name}));if(proposed.some(ev=>validateEvent(ev,null,existing)))continue;placed=proposed;break}
if(placed)generated.push(...placed);else failed.push(c.code)}db.events.push(...generated);save();render();let paperCount=new Set(generated.map(e=>e.courseId)).size;toast(`${paperCount} ${type==='exam'?'exam':'lecture'} papers scheduled across ${generated.length} room allocations${failed.length?`; ${failed.length} could not be placed`:''}.`);if(failed.length)openModal('Some courses could not be scheduled',`<div class="notice warn">${failed.length} course(s) were left unscheduled because no combination satisfied the capacity, time or conflict rules.</div><p><strong>${failed.map(esc).join(', ')}</strong></p><p class="small-note">Increase the schedule date range, review class sizes and venue availability, reduce the occupancy target, or change durations. Courses are shown in Reports and can be scheduled manually.</p>`,'Close')}
function saveSettings(){let slots=[...document.querySelectorAll('.cfgSlotStart')].map((x,i)=>({start:x.value,end:document.querySelectorAll('.cfgSlotEnd')[i].value}));if(slots.some(s=>!s.start||!s.end||mins(s.start)>=mins(s.end))){toast('Each period must have an end time after its start.');return}if(new Set(slots.map(s=>s.start)).size!==slots.length){toast('Period start times must be unique.');return}let start=$('#cfgStart').value,end=$('#cfgEnd').value;if(!start||!end||start>end){toast('Enter a valid academic date range.');return}let pct=Number($('#cfgExamCapacityPercent').value);if(!Number.isFinite(pct)||pct<50||pct>100){toast('Exam room occupancy target must be between 50% and 100%.');return}db.settings={...db.settings,session:$('#cfgSession').value.trim()||'Academic session',semester:$('#cfgSemester').value.trim()||'Semester',start,end,days:[...document.querySelectorAll('.cfgDay:checked')].map(x=>Number(x.value)).filter(n=>n!==0),slots,examDuration:Math.max(1,Number($('#cfgExamDuration').value)||1),examGap:Math.max(0,Number($('#cfgExamGap').value)||0),maxExamsPerCohortDay:Math.max(0,Number($('#cfgMaxExams').value)||0),examCapacityPercent:pct};save();toast('Academic settings saved.');render()}
function csvCell(v){let s=String(v??'');return '"'+s.replaceAll('"','""')+'"'}
function download(name,content,mime='text/csv;charset=utf-8'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type:mime}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportCSV(kind){let rows,headers;if(kind==='courses'){headers=['code','title','department','faculty','level','cohort','students','lecturer','duration','venueType'];rows=db.courses}else if(kind==='venues'){headers=['name','capacity','type','location','description','active'];rows=db.venues}else{headers=['type','courseCode','courseTitle','department','cohort','students','lecturer','date','start','end','venueName'];rows=db.events.filter(e=>!filters.type||page!=='schedule'||e.type===filters.type)}let csv=[headers.map(csvCell).join(','),...rows.map(r=>headers.map(h=>csvCell(r[h])).join(','))].join('\n');download(`fuk-${kind}-${db.settings.session.replace('/','-')}.csv`,'\ufeff'+csv);toast(`${rows.length} ${kind} exported as CSV.`)}
function parseCSV(txt){let rows=[],row=[],s='',q=false;for(let i=0;i<txt.length;i++){let c=txt[i];if(q&&c==='"'&&txt[i+1]==='"'){s+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){row.push(s);s=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&txt[i+1]==='\n')i++;row.push(s);if(row.some(x=>x.trim()))rows.push(row);row=[];s=''}else s+=c}row.push(s);if(row.some(x=>x.trim()))rows.push(row);if(!rows.length)return [];let h=rows.shift().map(x=>x.trim().replace(/^\uFEFF/,''));return rows.map(a=>Object.fromEntries(h.map((k,i)=>[k,(a[i]||'').trim()]))) }
function importCSV(kind,file){if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let rows=parseCSV(reader.result);if(!rows.length)throw Error('No data rows found.');if(kind==='courses'){let n=0;for(let r of rows){if(!r.code||!r.title||!r.cohort)continue;let old=db.courses.find(c=>c.code.toLowerCase()===r.code.toLowerCase());let data={id:old?.id||uid(),code:r.code,title:r.title,department:r.department||'',faculty:r.faculty||'',level:r.level||'',cohort:r.cohort,students:Number(r.students)||0,lecturer:r.lecturer||'',duration:Math.max(1,Number(r.duration)||1),venueType:r.venueType||'any'};if(old)Object.assign(old,data);else db.courses.push(data);n++}toast(`${n} course rows imported or updated.`)}else if(kind==='venues'){let n=0;for(let r of rows){if(!r.name)continue;let old=db.venues.find(v=>v.name.toLowerCase()===r.name.toLowerCase());let data={id:old?.id||uid(),name:r.name,capacity:r.capacity?Number(r.capacity):null,type:r.type||'classroom',location:r.location||'',description:r.description||'',active:r.active?String(r.active).toLowerCase()!=='false':true};if(old)Object.assign(old,data);else db.venues.push(data);n++}toast(`${n} venue rows imported or updated.`)}else throw Error('This import type is not supported.')}catch(e){toast('Import failed: '+e.message)}render()};reader.readAsText(file)}
function backup(){download(`fuk-timetable-backup-${db.settings.session.replace('/','-')}.json`,JSON.stringify(db,null,2),'application/json');toast('Full backup downloaded.')}
function restore(file){if(!file)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(!x.settings||!Array.isArray(x.courses)||!Array.isArray(x.venues)||!Array.isArray(x.events))throw Error('The selected file is not a FUK timetable backup.');if(confirm('Restore this backup? It will replace the current timetable data in this browser.')){db={...structuredClone(DEFAULT),...x};save();render();toast('Backup restored.')}}catch(e){toast(e.message)}};r.readAsText(file)}
function bind(){document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>nav(b.dataset.page));$('#quickGenerate').onclick=()=>{filters.type='lecture';nav('schedule')};$('#app').onclick=e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.go){nav(b.dataset.go);return}if(b.dataset.add){addEdit(b.dataset.add);return}if(b.dataset.edit){addEdit(b.dataset.edit,b.dataset.id);return}if(b.dataset.delete){deleteItem(b.dataset.delete,b.dataset.id);return}if(b.dataset.archive){let v=db.venues.find(x=>x.id===b.dataset.archive);if(db.events.some(x=>x.venueId===v.id)){toast('This venue is used by scheduled sessions. Move those sessions before archiving.');return}v.active=false;toast('Venue archived.');render();return}if(b.dataset.unarchive){db.venues.find(x=>x.id===b.dataset.unarchive).active=true;toast('Venue restored.');render();return}if(b.dataset.generate){generate(filters.type);return}if(b.dataset.print){window.print();return}if(b.dataset.saveSettings){saveSettings();return}if(b.dataset.addSlot!==undefined){db.settings.slots.push({start:'18:00',end:'20:00'});render();return}if(b.dataset.removeSlot!==undefined){if(db.settings.slots.length<=1){toast('Keep at least one time period.');return}db.settings.slots.splice(Number(b.dataset.removeSlot),1);render();return}if(b.dataset.export){exportCSV(b.dataset.export);return}if(b.dataset.import){let kind=b.dataset.import;let input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.onchange=()=>importCSV(kind,input.files[0]);input.click();return}if(b.dataset.backup){backup();return}if(b.dataset.restore){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=()=>restore(input.files[0]);input.click();return}};
$('#app').oninput=e=>{if(e.target.id==='courseSearch'||e.target.id==='venueSearch'){filters.search=e.target.value;let pos=e.target.selectionStart;render();let next=$('#'+e.target.id);next.focus();next.setSelectionRange(pos,pos)}};$('#app').onchange=e=>{if(e.target.id==='scheduleType'){filters.type=e.target.value;render()}if(e.target.id==='scheduleView'){filters.view=e.target.value;render()}if(e.target.id==='scheduleDate'){filters.date=e.target.value;render()}if(e.target.id==='scheduleDepartment'){filters.department=e.target.value;render()}}}
function init(){document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>nav(b.dataset.page));$('#quickGenerate').onclick=()=>nav('schedule');$('#app').onclick=e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.go){nav(b.dataset.go);return}if(b.dataset.add){addEdit(b.dataset.add);return}if(b.dataset.edit){addEdit(b.dataset.edit,b.dataset.id);return}if(b.dataset.delete){deleteItem(b.dataset.delete,b.dataset.id);return}if(b.dataset.archive){let v=db.venues.find(x=>x.id===b.dataset.archive);if(db.events.some(x=>x.venueId===v.id)){toast('This venue is used by scheduled sessions. Move those sessions before archiving.');return}v.active=false;toast('Venue archived.');render();return}if(b.dataset.unarchive){db.venues.find(x=>x.id===b.dataset.unarchive).active=true;toast('Venue restored.');render();return}if(b.dataset.generate!==undefined){generate(filters.type);return}if(b.dataset.print!==undefined){window.print();return}if(b.dataset.saveSettings!==undefined){saveSettings();return}if(b.dataset.addSlot!==undefined){db.settings.slots.push({start:'18:00',end:'20:00'});render();return}if(b.dataset.removeSlot!==undefined){if(db.settings.slots.length<=1){toast('Keep at least one time period.');return}db.settings.slots.splice(Number(b.dataset.removeSlot),1);render();return}if(b.dataset.export){exportCSV(b.dataset.export);return}if(b.dataset.import){let kind=b.dataset.import,input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.onchange=()=>importCSV(kind,input.files[0]);input.click();return}if(b.dataset.backup!==undefined){backup();return}if(b.dataset.restore!==undefined){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=()=>restore(input.files[0]);input.click();return}};
$('#app').oninput=e=>{if(e.target.id==='courseSearch'||e.target.id==='venueSearch'){filters.search=e.target.value;let pos=e.target.selectionStart;render();let next=$('#'+e.target.id);next.focus();next.setSelectionRange(pos,pos)}};$('#app').onchange=e=>{if(e.target.id==='scheduleType'){filters.type=e.target.value;render()}if(e.target.id==='scheduleView'){filters.view=e.target.value;render()}if(e.target.id==='scheduleDate'){filters.date=e.target.value;render()}if(e.target.id==='scheduleDepartment'){filters.department=e.target.value;render()}if(['summaryFaculty','summaryDepartment','summaryLevel'].includes(e.target.id))$('#app').querySelector('.exam-summary').innerHTML=`<div class="panel-head"><div><h3>Examination summaries by faculty, department and level</h3><p>Each paper shows every exam date, time, venue and allocated student count.</p></div><button class="button no-print" data-print>Print / Save PDF</button></div><div class="toolbar"><select class="select" id="summaryFaculty"><option value="">All faculties</option>${[...new Set(db.courses.map(c=>c.faculty).filter(Boolean))].sort().map(f=>`<option ${$('#summaryFaculty').value===f?'selected':''}>${esc(f)}</option>`).join('')}</select><select class="select" id="summaryDepartment"><option value="">All departments</option>${[...new Set(db.courses.map(c=>c.department).filter(Boolean))].sort().map(f=>`<option ${$('#summaryDepartment').value===f?'selected':''}>${esc(f)}</option>`).join('')}</select><select class="select" id="summaryLevel"><option value="">All levels</option>${[...new Set(db.courses.map(c=>c.level).filter(Boolean))].sort().map(f=>`<option ${$('#summaryLevel').value===f?'selected':''}>${esc(f)}</option>`).join('')}</select></div>${renderExamSummaryTables()}`};render()}
boot();
